import collections
import json
import subprocess
import sys

s, new_binary, out_path, *repos = sys.argv[1:]


def stream(cmd, args):
    proc = subprocess.run(
        cmd + args, stdin=subprocess.DEVNULL, capture_output=True, text=True
    )
    for line in proc.stdout.splitlines():
        if line.startswith("{"):
            yield json.loads(line)


def symbols(cmd, repo):
    return {
        r["id"]: r
        for r in stream(cmd, ["symbols", "--repo", repo, "--format", "ndjson"])
        if r.get("record_type") == "symbol"
    }


def failing(cmd, repo):
    out = subprocess.run(
        cmd + ["health", "--repo", repo, "--json"],
        stdin=subprocess.DEVNULL,
        capture_output=True,
        text=True,
    ).stdout
    return {
        p["file_path"]
        for p in json.loads(out).get("partial_failures", [])
        if p.get("code") == "E_PARSE_ERROR"
    }


old_cmd = ["entire", "graph"]
report = {}
for name in repos:
    repo = f"{s}/bench-cache/Rust/{name}"
    a, b = symbols(old_cmd, repo), symbols([new_binary], repo)
    fail_a, fail_b = failing(old_cmd, repo), failing([new_binary], repo)
    missing = [a[i] for i in a.keys() - b.keys()]
    added = [b[i] for i in b.keys() - a.keys()]

    def status(sym):
        f = sym["file_path"]
        if f in fail_b and f not in fail_a:
            return "file newly fails"
        if f in fail_a and f not in fail_b:
            return "file failed before, parses now"
        if f in fail_a and f in fail_b:
            return "file fails in both"
        return "file parses in both"

    summary = {
        "bundled": len(a),
        "new": len(b),
        "missing": collections.Counter(status(m) for m in missing),
        "added": collections.Counter(status(m) for m in added),
        "missing_kinds_parse_both": collections.Counter(
            m["kind"] for m in missing if status(m) == "file parses in both"
        ),
        "added_kinds_parse_both": collections.Counter(
            m["kind"] for m in added if status(m) == "file parses in both"
        ),
    }
    report[name] = {
        "summary": summary,
        "missing_parse_both": sorted(
            (m["file_path"], m["start_line"], m["kind"], m["qualified_name"])
            for m in missing
            if status(m) == "file parses in both"
        ),
        "added_parse_both": sorted(
            (m["file_path"], m["start_line"], m["kind"], m["qualified_name"])
            for m in added
            if status(m) == "file parses in both"
        ),
        "missing_newly_fails": sorted(
            (m["file_path"], m["start_line"], m["kind"], m["qualified_name"])
            for m in missing
            if status(m) == "file newly fails"
        ),
    }
    print(name, json.dumps({k: (dict(v) if isinstance(v, collections.Counter) else v) for k, v in summary.items()}), flush=True)

json.dump(report, open(out_path, "w"), indent=1, default=list)

