import json
import re
import subprocess
import sys

s, *repos = sys.argv[1:]
masked, unmasked = [f"{s}/entire-graph-rust24"], [f"{s}/entire-graph-nomask"]


def run(cmd, args):
    return subprocess.run(
        cmd + args, stdin=subprocess.DEVNULL, capture_output=True, text=True
    ).stdout


def failing(cmd, repo):
    out = json.loads(run(cmd, ["health", "--repo", repo, "--json"]))
    return {
        p["file_path"]: p.get("detail", "")
        for p in out.get("partial_failures", [])
        if p.get("code") == "E_PARSE_ERROR"
    }


def per_file_symbols(cmd, repo):
    counts = collections.Counter()
    for line in run(cmd, ["symbols", "--repo", repo, "--format", "ndjson"]).splitlines():
        if line.startswith("{"):
            r = json.loads(line)
            if r.get("record_type") == "symbol":
                counts[r["file_path"]] += 1
    return counts


macro_name = re.compile(r"near \"([^\"]{0,60})")
for name in repos:
    repo = f"{s}/bench-cache/Rust/{name}"
    fm, fu = failing(masked, repo), failing(unmasked, repo)
    only_mask = sorted(set(fm) - set(fu))
    only_nomask = sorted(set(fu) - set(fm))
    sm, su = per_file_symbols(masked, repo), per_file_symbols(unmasked, repo)
    gained = sum(sm[f] - su[f] for f in only_mask)
    print(f"== {name}: fail with mask {len(fm)}, without {len(fu)}")
    print(f"   fail ONLY with mask: {len(only_mask)} files; symbols in them: mask {sum(sm[f] for f in only_mask)} vs no-mask {sum(su[f] for f in only_mask)} ({gained:+d})")
